def run(company_name, website, meeting_focus, headquarters, search_results, site_text, site_title, site_url, site_error):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    company = clean(company_name) or 'the company'
    focus = clean(meeting_focus) or 'general'
    hq = clean(headquarters)
    site = clean(website)

    facts = []

    if hq:
        facts.append({'label': 'headquarters', 'value': hq, 'source': 'input', 'confidence': 'medium'})
    if site:
        facts.append({'label': 'website', 'value': site, 'source': 'input', 'confidence': 'high'})

    if isinstance(search_results, list):
        for r in search_results[:5]:
            if isinstance(r, dict):
                title = clean(r.get('title'))
                content = clean(r.get('content'))
                url = clean(r.get('url'))
                text = ' | '.join([x for x in [title, content[:220], url] if x])
                if text:
                    low = text.lower()
                    label = 'search_hit'
                    confidence = 'low'
                    if any(k in low for k in ['president', 'ceo', 'chief executive', 'chair', 'founder', 'leadership']):
                        label = 'leadership_claim'
                    if any(k in low for k in ['revenue', 'funding', 'million', 'billion', '$']):
                        label = 'financial_claim'
                    if any(k in low for k in ['april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december', '2025', '2024', '2023']):
                        label = 'dated_claim'
                    facts.append({'label': label, 'value': text[:360], 'source': url or 'search', 'confidence': confidence})

    if isinstance(site_title, str) and site_title.strip():
        facts.append({'label': 'site_title', 'value': clean(site_title)[:200], 'source': clean(site_url) or 'website', 'confidence': 'high'})
    if isinstance(site_text, str) and site_text.strip():
        text = clean(site_text)
        facts.append({'label': 'site_text', 'value': text[:900], 'source': clean(site_url) or 'website', 'confidence': 'high'})
    if isinstance(site_error, str) and site_error.strip():
        facts.append({'label': 'site_error', 'value': clean(site_error)[:200], 'source': 'fetch', 'confidence': 'low'})

    dedup = []
    seen = set()
    for f in facts:
        key = (f.get('label', '') + '|' + f.get('value', '')).lower()
        if key not in seen:
            seen.add(key)
            dedup.append(f)

    return {'facts': dedup[:10], 'company_name': company, 'meeting_focus': focus}

def run(facts, meeting_focus):
    facts = facts if isinstance(facts, list) else []
    score = 0
    reasons = []
    has_site = False
    has_search = False
    conflicting_leadership = False
    has_unsupported_financial = False
    has_dated_claim = False

    leadership_claims = []

    for f in facts:
        label = (f.get('label') or '').lower()
        value = (f.get('value') or '').strip()
        conf = (f.get('confidence') or '').lower()
        if not value:
            continue
        if label in ('website', 'site_url', 'site_title', 'site_text'):
            has_site = True
            score += 1
        if label in ('search_hit', 'leadership_claim', 'financial_claim', 'dated_claim'):
            has_search = True
            score += 1
        if label == 'headquarters':
            score += 1
        if label == 'leadership_claim':
            leadership_claims.append(value.lower())
        if label == 'financial_claim' and conf != 'high':
            has_unsupported_financial = True
        if label == 'dated_claim':
            has_dated_claim = True

    if len(leadership_claims) >= 2:
        unique_names = set()
        for v in leadership_claims:
            for token in [' tim ', ' walter ', ' johnsen ', ' broderick ', ' president ', ' ceo ', ' chief executive ', ' founder ']:
                if token.strip() in v:
                    unique_names.add(v)
        if len(unique_names) >= 2:
            conflicting_leadership = True

    if has_site:
        reasons.append('Official site or site metadata found.')
    if has_search:
        reasons.append('Public search results found.')
    if conflicting_leadership:
        reasons.append('Conflicting leadership claims were found.')
        score -= 1
    if has_unsupported_financial:
        reasons.append('Financial figures appear in search hits but are not independently verified.')
        score -= 1
    if has_dated_claim:
        reasons.append('Recent dated claims were found in search results.')

    escalate = score < 2 or conflicting_leadership or has_unsupported_financial
    verdict = 'ready' if not escalate else 'needs_escalation'
    return {'score': score, 'verdict': verdict, 'reasons': reasons, 'escalate': escalate}

def run(company_name, website, meeting_focus, facts, judge, escalation_result):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    def fmt_money(text):
        s = clean(text)
        if not s:
            return s
        s = s.replace('one million five thousand dollars', '$1.05M')
        s = s.replace('1.050M', '$1.05M').replace('1.05M', '$1.05M')
        return s

    def fmt_date(text):
        s = clean(text)
        if 'April of twenty twenty-five' in s:
            s = s.replace('April of twenty twenty-five', 'April 2025')
        if 'April of 2025' in s:
            s = s.replace('April of 2025', 'April 2025')
        return s

    company = company_name or 'the company'
    focus = meeting_focus or 'general'
    facts = facts if isinstance(facts, list) else []
    judge = judge if isinstance(judge, dict) else {}
    escalation = clean(escalation_result)

    leadership_claims = []
    financial_claims = []
    dated_claims = []
    other_facts = []
    had_any_facts = False

    for f in facts[:10]:
        label = (f.get('label') or 'fact').lower()
        value = clean(f.get('value'))
        if not value:
            continue
        had_any_facts = True
        value = fmt_date(fmt_money(value))
        if label == 'leadership_claim':
            leadership_claims.append(value)
        elif label == 'financial_claim':
            financial_claims.append(value)
        elif label == 'dated_claim':
            dated_claims.append(value)
        elif label in ('website', 'headquarters', 'site_title'):
            other_facts.append(f'- **{label}**: {value}')
        elif label == 'site_error':
            other_facts.append(f'- **site error**: {value}')

    if leadership_claims:
        if len(set(x.lower() for x in leadership_claims)) > 1:
            other_facts.append(f'- **leadership**: conflicting public references found; treat leadership as unconfirmed: {"; ".join(leadership_claims[:3])}')
        else:
            other_facts.append(f'- **leadership**: {leadership_claims[0]}')

    for v in financial_claims[:3]:
        other_facts.append(f'- **financial claim**: {v} (unverified unless sourced from the official site)')
    for v in dated_claims[:3]:
        other_facts.append(f'- **dated claim**: {v}')

    if escalation:
        other_facts.append(f'- **escalation notes**: {escalation[:1200]}')

    if judge.get('escalate'):
        speech = f'Briefing is partial, sir. I found some public signals, but there are conflicts or unverified claims, so I have kept the summary cautious.'
    else:
        speech = f'Briefing ready, sir. I have a concise summary of {company} focused on {focus}, with only the confirmed public facts included.'

    if had_any_facts:
        key_facts_block = chr(10).join(other_facts) if other_facts else '- No reliable facts collected.'
    else:
        key_facts_block = '- No reliable facts collected.\n- Deeper research unavailable.'

    report = f'''# Company Briefing

## Verdict
- **Status:** {judge.get('verdict', 'unknown')}
- **Score:** {judge.get('score', 0)}
- **Focus:** {focus}

## Company
- **Name:** {company}
- **Website:** {website or 'not provided'}

## Key facts
{key_facts_block}

## Notes
- Any conflicting leadership references are flagged, not resolved.
- Financial figures from search snippets are treated as claims unless independently confirmed.
- Dates are rendered in a normal spoken style, for example: April 2025.
- Verify any mission-critical figures before the meeting.
'''
    return {'speech': speech[:900], 'report': report}
